                    "sql": "create or replace table maplemonk.saadaa_inventory_sales_fact_items as with grn as ( select grn_created_date, sku, sum(received_quantity) inwarded_quantity from maplemonk.saadaa_grn_fact_items where sku is not null group by 1,2 ), total_grn as ( select grn_created_date, sum(received_quantity) inwarded_quantity from maplemonk.saadaa_grn_fact_items group by 1 ), sales as ( select date(order_date) order_date, commonsku, sum(ifnull(quantity,0)) sold_quantity from maplemonk.saadaa_sales_consolidated where lower(GROSS_ORDER_TYPE) like \'%sale%\' and marketplace in (\'AMAZON\',\'WEBSITE\',\'AMAZON_FBA\',\'MYNTRA PPMP\',\'CRED-API\',\'B2B\') and warehouse in (\'SAADAA SUSTAINABLE DESIGNS AND TECHNOLOGIES PRIVATE LIMITED\',\'AMAZON_FBA_XIR6_AUTO\',\'HOLISOL - BLR\',\'EBO001\',\'HOLISOL-MH\') group by 1,2 ), total_sales as ( select date(order_date) order_date, sum(ifnull(quantity,0)) sold_quantity from maplemonk.saadaa_sales_consolidated where lower(GROSS_ORDER_TYPE) like \'%sale%\' and marketplace in (\'AMAZON\',\'WEBSITE\',\'AMAZON_FBA\',\'MYNTRA PPMP\',\'CRED-API\',\'B2B\') and warehouse in (\'SAADAA SUSTAINABLE DESIGNS AND TECHNOLOGIES PRIVATE LIMITED\',\'AMAZON_FBA_XIR6_AUTO\',\'HOLISOL - BLR\',\'EBO001\',\'HOLISOL-MH\') group by 1 ) select g.grn_created_date, g.sku, sm.product_id, sm.product_name, sm.category, sm.size, sm.color, sm.item_category, sm.categorytype, sm.gender, sm.Product_Launch_Date, sm.Product_Variant, sm.Sub_category, g.inwarded_quantity, ifnull(s.sold_quantity,0) sold_quantity, tg.inwarded_quantity as total_inwarded_quantity, ifnull(ts.sold_quantity,0) total_sold_quantity from grn g left join total_grn tg on date(g.grn_created_date) = date(tg.grn_created_date) left join sales s on date(g.grn_created_date) = date(s.order_date) and lower(g.sku) = lower(s.commonsku) left join total_sales ts on date(g.grn_created_date) = date(ts.order_date) left join ( select commonsku, product_id, product_name, category, size, color, item_category, categorytype, gender, Product_Launch_Date, Product_Variant, Sub_category from `MAPLEMONK.saadaa_final_sku_master` qualify row_number() over (partition by commonsku order by 1) = 1 ) sm on lower(sm.commonsku) = lower(g.sku) ; create or replace table maplemonk.saadaa_isr_summary as select \"Last Day\" as period, avg(ifnull(total_sold_quantity,0)) total_sales, avg(ifnull(total_inwarded_quantity,0)) as total_grn, safe_divide(avg(ifnull(total_inwarded_quantity,0)),avg(ifnull(total_sold_quantity,0))) as ISR from maplemonk.saadaa_inventory_sales_fact_items where date(grn_created_date) = DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY) group by 1 UNION ALL select \"Last Week\" as period, sum(total_sales) total_sales, sum(total_grn) total_grn, safe_divide(sum(total_grn),sum(total_sales)) as ISR from (select grn_created_date, avg(ifnull(total_sold_quantity,0)) total_sales, avg(ifnull(total_inwarded_quantity,0)) as total_grn, safe_divide(sum(ifnull(total_inwarded_quantity,0)),sum(ifnull(total_sold_quantity,0))) as ISR from maplemonk.saadaa_inventory_sales_fact_items where DATE(grn_created_date) >= DATE_SUB(CURRENT_DATE(), INTERVAL 6 DAY) AND DATE(grn_created_date) <= CURRENT_DATE() group by 1 ) group by 1 UNION ALL select \"MTD\" as period, sum(total_sales) total_sales, sum(total_grn) total_grn, safe_divide(sum(total_grn),sum(total_sales)) as ISR from ( select grn_created_date, avg(ifnull(total_sold_quantity,0)) total_sales, avg(ifnull(total_inwarded_quantity,0)) as total_grn, safe_divide(sum(ifnull(total_inwarded_quantity,0)),sum(ifnull(total_sold_quantity,0))) as ISR from maplemonk.saadaa_inventory_sales_fact_items where DATE_TRUNC(DATE(grn_created_date), MONTH) = DATE_TRUNC(CURRENT_DATE(), MONTH) group by 1 ) group by 1 ;",
